function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 12) return 's needs 1 to 12 characters.';
  if (!/^[a-zA-Z0-9]+$/.test(s)) return 's may contain only letters and digits.';
  return null;
}

