function letterCasePermutation(s) {
  const result = [];
  const chars = s.split('');

  function backtrack(index) {
    if (index === chars.length) {
      result.push(chars.join(''));
      return;
    }
    const ch = chars[index];
    if (/[0-9]/.test(ch)) {
      backtrack(index + 1);
      return;
    }
    chars[index] = ch.toLowerCase();
    backtrack(index + 1);
    chars[index] = ch.toUpperCase();
    backtrack(index + 1);
    chars[index] = ch;
  }

  backtrack(0);
  return result;
}

