function letterCasePermutation(s) {
  const letters = [];
  for (let i = 0; i < s.length; i++) if (/[a-zA-Z]/.test(s[i])) letters.push(i);
  const out = new Set();
  for (let mask = 0; mask < (1 << letters.length); mask++) {
    const arr = s.toLowerCase().split('');
    for (let b = 0; b < letters.length; b++) {
      if (mask & (1 << b)) arr[letters[b]] = arr[letters[b]].toUpperCase();
    }
    out.add(arr.join(''));
  }
  return [...out];
}

