function generate(rand, size) {
  const pool = 'abcxyzABCXYZ0123456789';
  const n = size === 'large' ? 12 : 1 + Math.floor(rand() * 6);
  let s = '';
  for (let i = 0; i < n; i++) s += pool[Math.floor(rand() * pool.length)];
  return [s];
}
